1	// Fresh and upgraded application-schema verification; every write is rolled back.
2	// Supabase-owned auth/storage setup is excluded from the fresh replay.
3	import assert from "node:assert/strict";
4	import { readFileSync, readdirSync } from "node:fs";
5	import postgres from "postgres";
6	import { applicationMigrationSql, canonicalFunctionDefinition, replayMigrations } from "./migration-replay.mjs";
7	
8	process.loadEnvFile(".env");
9	if (!process.env.SUPABASE_DB_URL) throw new Error("SUPABASE_DB_URL is required");
10	const project = new URL(process.env.NEXT_PUBLIC_SUPABASE_URL).hostname.split(".")[0];
11	const connection = new URL(process.env.SUPABASE_DB_URL);
12	assert(connection.hostname === `db.${project}.supabase.co` || connection.username.endsWith(`.${project}`),
13	  "Database connection must match the configured Supabase project");
14	const db = postgres(connection.toString(), { ssl: "require", max: 1, connect_timeout: 10, onnotice: () => {},
15	  connection: { application_name: process.env.MONEO_MIGRATION_QA_APP_NAME ?? "moneo-migration-qa", lock_timeout: "10s", statement_timeout: "120s" } });
16	const files = readdirSync("supabase/migrations").filter(file => file.endsWith(".sql")).sort();
17	const migrations = files.map(file => ({ file, version: file.split("_")[0], sql: readFileSync(`supabase/migrations/${file}`, "utf8") }));
18	const regressionFiles = readdirSync("supabase/tests").filter(file => file.endsWith(".sql")).sort();
19	const functionNames = [...new Set(migrations.flatMap(migration => [
20	  ...migration.sql.matchAll(/create (?:or replace )?function public\.(\w+)/g),
21	  ...migration.sql.matchAll(/alter function public\.\w+\([^;]*\) rename to (\w+)/g),
22	].map(match => match[1])))];
23	const schema = `moneo_migration_qa_${Date.now()}`;
24	const rollback = new Error("Successful rollback-only verification");
25	
26	async function metadata(tx, name) {
27	  return {
28	    columns: await tx`select table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema=${name} order by table_name,ordinal_position`,
29	    constraints: await tx`select cl.relname table_name,c.conname,c.contype,c.confdeltype,pg_get_constraintdef(c.oid) definition from pg_constraint c join pg_class cl on cl.oid=c.conrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname=${name} order by cl.relname,c.conname`,
30	    indexes: await tx`select tablename,indexname,indexdef from pg_indexes where schemaname=${name} order by tablename,indexname`,
31	    policies: await tx`select tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname=${name} order by tablename,policyname`,
32	    rls: await tx`select c.relname table_name,c.relrowsecurity enabled from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=${name} and c.relkind='r' order by c.relname`,
33	    views: await tx`select c.relname name,c.reloptions options,pg_get_viewdef(c.oid) definition from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=${name} and c.relkind='v' order by c.relname`,
34	    triggers: await tx`select c.relname table_name,t.tgname name,t.tgenabled enabled,pg_get_triggerdef(t.oid) definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname=${name} and not t.tgisinternal order by c.relname,t.tgname`,
35	    functions: await tx`select p.proname name,pg_get_function_identity_arguments(p.oid) arguments,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=${name} and p.proname = any(${functionNames}) order by p.proname,arguments`,
36	  };
37	}
38	
39	function normalize(rows, functions = false) {
40	  return rows.filter(row => row.table_name !== "auth_users" && row.tablename !== "auth_users")
41	    .map(row => Object.fromEntries(Object.entries(row).map(([key, value]) => [key,
42	      typeof value === "string" ? (functions && key === "definition" ? canonicalFunctionDefinition(value) : value).replaceAll(`${schema}.auth_users`, "auth.users")
43	        .replaceAll(`${schema}.`, "").replaceAll("public.", "") : value])));
44	}
45	
46	async function rolledBack(work) {
47	  try { await db.begin(async tx => { await work(tx); throw rollback; }); }
48	  catch (error) { if (error !== rollback) throw error; }
49	}
50	
51	try {
52	  const applied = await db`select version from supabase_migrations.schema_migrations order by version`;
53	  const pending = migrations.filter(migration => !applied.some(row => row.version === migration.version));
54	  let fresh, upgraded;
55	  await rolledBack(async tx => {
56	    await tx.unsafe(`create schema ${schema}; create table ${schema}.auth_users (id uuid primary key, email text)`);
57	    // Supabase supplies schema USAGE; grant it only on the disposable replay schema.
58	    await tx.unsafe(`grant usage on schema ${schema} to authenticated, service_role`);
59	    const isolated = sql => sql.replace(/\bpublic\./g, `${schema}.`).replace(/\bauth\.users\b/g, `${schema}.auth_users`);
60	    const isolatedMigrations = migrations.map(migration => {
61	      const text = applicationMigrationSql(migration.file, migration.sql, schema);
62	      return { ...migration, sql: isolated(text) };
63	    });
64	    await replayMigrations(tx, isolatedMigrations, "fresh");
65	    for (const file of regressionFiles) {
66	      try { await tx.unsafe(isolated(readFileSync(`supabase/tests/${file}`, "utf8"))); }
67	      catch (cause) { throw new Error(`Fresh SQL regression ${file}: ${cause.message}`, { cause }); }
68	    }
69	    fresh = await metadata(tx, schema);
70	  });
71	  assert.equal((await db`select 1 from pg_namespace where nspname=${schema}`).length, 0, "QA schema must be rolled back");
72	  console.log(`PASS: fresh replay ${migrations.length} migrations and ${regressionFiles.length} SQL regressions; disposable schema rollback verified`);
73	  await rolledBack(async tx => {
74	    await replayMigrations(tx, pending, "upgrade");
75	    for (const file of regressionFiles) {
76	      try { await tx.unsafe(readFileSync(`supabase/tests/${file}`, "utf8")); }
77	      catch (cause) { throw new Error(`Upgrade SQL regression ${file}: ${cause.message}`, { cause }); }
78	    }
79	    upgraded = await metadata(tx, "public");
80	  });
81	  for (const key of Object.keys(fresh)) assert.deepEqual(normalize(fresh[key], key === "functions"), normalize(upgraded[key], key === "functions"), `${key}: fresh and upgraded schema differ`);
82	  assert.deepEqual(await db`select version from supabase_migrations.schema_migrations order by version`, applied,
83	    "Rollback-only verification must not change migration history");
84	  console.log(`PASS: ${migrations.length} migrations, ${pending.length} pending upgrades, ${regressionFiles.length} SQL regressions; columns/constraints/indexes/RLS/policies/views/triggers/functions match; rollback verified`);
85	} finally { await db.end(); }
86

1	// Logs/reports can contain identifying application evidence: keep them ignored.
2	import { spawnSync, execFileSync } from "node:child_process";
3	import { existsSync, mkdirSync, openSync, closeSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
4	import { resolve } from "node:path";
5	import { assertProductionBuild, assertRequiredResults } from "./acceptance-results.mjs";
6	
7	if (existsSync(".env")) process.loadEnvFile(".env");
8	const tier = process.argv[2];
9	if (!["fast", "required"].includes(tier)) throw new Error("Use acceptance.mjs fast|required");
10	const directory = resolve(`.qa/acceptance-${tier}-${Date.now()}`);
11	mkdirSync(directory, { recursive: true });
12	const revision = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
13	const worktreeDirty = Boolean(execFileSync("git", ["status", "--porcelain"], { encoding: "utf8" }).trim());
14	const migrationHead = readdirSync("supabase/migrations").filter(file => file.endsWith(".sql")).sort().at(-1);
15	const result = { revision, worktreeDirty, migrationHead, tier, environment: "local configured Supabase (not deployed acceptance)", startedAt: new Date().toISOString(), provider: "optional; not run; core-journey.gated.spec.ts excluded because it invokes the live provider; deterministic mocks are not provider evaluation", checks: [] };
16	
17	function run(name, script, args = [], env = {}) {
18	  const log = openSync(`${directory}/${name}.log`, "w");
19	  let child;
20	  try { child = spawnSync(process.execPath, [script, ...args], { env: { ...process.env, ...env }, stdio: ["ignore", log, log] }); }
21	  finally { closeSync(log); }
22	  result.checks.push({ name, passed: child.status === 0 });
23	  if (child.error || child.status !== 0) throw new Error(`${name} failed; review ignored acceptance logs`);
24	  console.log(`PASS: ${name}`);
25	}
26	
27	try {
28	  if (tier === "fast") {
29	    const npm = process.env.npm_execpath;
30	    if (!npm) throw new Error("Run through npm run acceptance:fast");
31	    for (const name of ["test", "lint", "build"]) run(name, npm, ["run", name]);
32	    result.buildId = readFileSync(".next/BUILD_ID", "utf8").trim();
33	  } else {
34	    const latestFast = readdirSync(".qa").filter(name => /^acceptance-fast-\d+$/.test(name)).sort().at(-1);
35	    let fast;
36	    try { if (latestFast) fast = JSON.parse(readFileSync(`.qa/${latestFast}/result.json`, "utf8")); } catch { /* Missing/incomplete evidence is rejected below. */ }
37	    const buildId = existsSync(".next/BUILD_ID") ? readFileSync(".next/BUILD_ID", "utf8").trim() : undefined;
38	    assertProductionBuild(fast, { revision, worktreeDirty, buildId });
39	    result.buildId = buildId;
40	    const missing = ["SUPABASE_DB_URL", "SUPABASE_SERVICE_ROLE_KEY", "NEXT_PUBLIC_SUPABASE_URL", "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"].filter(name => !process.env[name]);
41	    const state = process.env.E2E_STORAGE_STATE || "e2e/.auth.json";
42	    if (!existsSync(state)) missing.push("E2E_STORAGE_STATE (or e2e/.auth.json)");
43	    if (missing.length) throw new Error(`Required prerequisites missing: ${missing.join(", ")}`);
44	    run("privacy", "scripts/check-private-data.mjs");
45	    run("migrations", "supabase/tests/migrations.mjs");
46	    const units = `${directory}/units.json`, browser = `${directory}/browser.json`;
47	    // Live fixture DDL locks shared auth/workspace tables. Serialize files while
48	    // retaining each test's deliberate concurrent database connections.
49	    run("units", "node_modules/vitest/vitest.mjs", ["run", "--no-file-parallelism", "--reporter=json", `--outputFile=${units}`], { RUN_RESERVATION_DB_TESTS: "1", RUN_IMPORT_EXCLUSION_DB_TESTS: "1", RUN_IMPORT_ROW_UNDO_DB_TESTS: "1", RUN_VERIFIED_EVIDENCE_DB_TESTS: "1", RUN_INVESTIGATION_REQUEST_DB_TESTS: "1" });
50	    const unitReport = JSON.parse(readFileSync(units, "utf8"));
51	    result.units = { total: unitReport.numTotalTests, failed: unitReport.numFailedTests, skipped: unitReport.numPendingTests };
52	    assertRequiredResults("vitest", unitReport);
53	    const specs = readdirSync("e2e").filter(file => file.endsWith(".spec.ts") && file !== "core-journey.gated.spec.ts").map(file => `e2e/${file}`);
54	    // Run the verified production build without HMR or a live provider key.
55	    run("browser", "node_modules/@playwright/test/cli.js", ["test", ...specs, "--workers=1", "--reporter=json", `--output=${directory}/browser-artifacts`], { PLAYWRIGHT_JSON_OUTPUT_FILE: browser, OPENAI_API_KEY: "", E2E_PRODUCTION_BUILD: "1", CI: "1" });
56	    const browserReport = JSON.parse(readFileSync(browser, "utf8"));
57	    result.browser = browserReport.stats;
58	    assertRequiredResults("playwright", browserReport);
59	  }
60	  result.passed = true;
61	} catch (error) {
62	  result.passed = false;
63	  result.failure = error.message;
64	  console.error(error.message);
65	  process.exitCode = 1;
66	} finally {
67	  result.finishedAt = new Date().toISOString();
68	  writeFileSync(`${directory}/result.json`, JSON.stringify(result, null, 2));
69	  console.log(`Acceptance summary: ${directory}/result.json`);
70	}
