10	// Historical pg_get_functiondef bodies retain checkout newlines. Only code
11	// whitespace is equivalent; quoted data and the generated header stay exact.
12	export function canonicalFunctionDefinition(definition) {
13	  const opening = /^[ \t]*AS (\$(?:[A-Za-z_\u0080-\uffff][A-Za-z_0-9\u0080-\uffff]*)?\$)/m.exec(definition);
14	  if (!opening || !/\bLANGUAGE (?:sql|plpgsql)\b/.test(definition.slice(0, opening.index))) return definition;
15	  const start = opening.index + opening[0].length;
16	  const end = definition.lastIndexOf(opening[1]);
17	  if (end < start) return definition;
18	  const body = definition.slice(start, end);
19	  let normalized = "";
20	  for (let index = 0; index < body.length;) {
21	    const from = index, quote = body[index];
22	    if (quote === "'" || quote === '"') {
23	      const escaped = quote === "'" && /[eE]/.test(body[index - 1] ?? "") && !/[\w$\u0080-\uffff]/.test(body[index - 2] ?? "");
24	      index++;
25	      while (index < body.length) {
26	        // Unknown standard_conforming_strings: fail closed on ambiguous quotes.
27	        if (!escaped && quote === "'" && body[index] === "\\" && body[index + 1] === "'") return definition;
28	        if (escaped && body[index] === "\\") { index += 2; continue; }
29	        if (body[index++] === quote) { if (body[index] !== quote) break; index++; }
30	      }
31	      normalized += body.slice(from, index);
32	    } else if (body.startsWith("--", index)) {
33	      const newline = body.indexOf("\n", index);
34	      index = newline < 0 ? body.length : newline + 1;
35	      normalized += body.slice(from, index).replaceAll("\r\n", "\n");
36	    } else if (body.startsWith("/*", index)) {
37	      let depth = 1;
38	      index += 2;
39	      while (index < body.length && depth) {
40	        if (body.startsWith("/*", index)) { depth++; index += 2; }
41	        else if (body.startsWith("*/", index)) { depth--; index += 2; }
42	        else index++;
43	      }
44	      normalized += body.slice(from, index).replaceAll("\r\n", "\n");
45	    } else {
46	      const delimiter = !/[\w$\u0080-\uffff]/.test(body[index - 1] ?? "") && /^(\$(?:[A-Za-z_\u0080-\uffff][A-Za-z_0-9\u0080-\uffff]*)?\$)/.exec(body.slice(index));
47	      if (delimiter) {
48	        const closing = body.indexOf(delimiter[1], index + delimiter[1].length);
49	        if (closing < 0) return definition;
50	        index = closing + delimiter[1].length;
51	        normalized += body.slice(from, index);
52	      } else if (body.startsWith("\r\n", index)) { normalized += "\n"; index += 2; }
53	      else normalized += body[index++];
54	    }
55	  }
56	  return definition.slice(0, start) + normalized + definition.slice(end);
57	}
