59	/** @param {string} file @param {string} sql @param {string} [schema] */
60	export function applicationMigrationSql(file, sql, schema) {
61	  if (schema) {
62	    if (!/^[a-z_][a-z0-9_]*$/.test(schema)) throw new Error("Invalid disposable schema name");
63	    sql = sql.replace(/\bn\.nspname(\s*=\s*)'public'/g, `n.nspname$1'${schema}'`);
64	  }
65	  if (file.endsWith("_initial.sql")) {
66	    const boundary = sql.indexOf("insert into storage.buckets");
67	    if (boundary < 0) throw new Error("Initial storage boundary changed; review disposable replay isolation");
68	    return sql.slice(0, boundary);
69	  }
70	  if (file === "202610270003_chat_attachments.sql") {
71	    const boundary = sql.indexOf("alter table public.messages");
72	    if (boundary < 0) throw new Error("Chat storage boundary changed; review disposable replay isolation");
73	    return sql.slice(boundary);
74	  }
75	  if (file === "202610200003_remove_artifacts_and_library.sql") {
76	    const start = sql.indexOf("drop policy private_finance_files on storage.objects;");
77	    const end = sql.indexOf("create or replace function public.reset_workspace()", start);
78	    if (start < 0 || end < 0) throw new Error("Storage policy boundary changed; review disposable replay isolation");
79	    return sql.slice(0, start) + sql.slice(end);
80	  }
81	  return sql;
82	}
