39	  if tg_op <> 'INSERT' then
40	    previous := to_jsonb(old);
41	    previous := jsonb_set(previous, array[money_key], to_jsonb(previous->>money_key));
42	  end if;
43	  if tg_op <> 'DELETE' then
44	    current_value := to_jsonb(new);
45	    current_value := jsonb_set(current_value, array[money_key], to_jsonb(current_value->>money_key));
46	  end if;
47	  insert into public.planning_events(workspace_id, entity_type, entity_id, actor_id, before, after, request_id)
48	  values(coalesce(new.workspace_id, old.workspace_id), case when tg_table_name = 'financial_assumptions' then 'assumption' else 'spending_plan' end,
49	    coalesce(new.id, old.id), auth.uid(), previous, current_value,
50	    nullif(current_setting('moneo.planning_request_id', true), '')::uuid);
51	  return coalesce(new, old);
52	end;
